#!/bin/bash
# Uninstall script for GitHub Copilot CLI
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling GitHub Copilot CLI..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping GitHub Copilot CLI if running..."
pkill -f "GitHub Copilot CLI" 2>/dev/null || true

# Remove /usr/local/bin/copilot
echo "Removing /usr/local/bin/copilot..."
if [ -d "/usr/local/bin/copilot" ]; then
    rm -rf "/usr/local/bin/copilot" 2>/dev/null || true
elif [ -f "/usr/local/bin/copilot" ]; then
    rm -f "/usr/local/bin/copilot" 2>/dev/null || true
fi

# Remove $HOME/.copilot
echo "Removing $HOME/.copilot..."
if [ -d "$HOME/.copilot" ]; then
    rm -rf "$HOME/.copilot" 2>/dev/null || true
elif [ -f "$HOME/.copilot" ]; then
    rm -f "$HOME/.copilot" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/copilot
echo "Removing $HOME/Library/Caches/copilot..."
if [ -d "$HOME/Library/Caches/copilot" ]; then
    rm -rf "$HOME/Library/Caches/copilot" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/copilot" ]; then
    rm -f "$HOME/Library/Caches/copilot" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
